Q: Get base class for a type in class hierarchy A: <p>I know I'm late to the party, but I also needed something like this right now.<br />
I came up with a C++23 solution that works on aggregates. It uses friend injection - this was described pretty well in <a href="https://stackoverflow.com/a/76843045">@linkhyrule5`s answer</a>.</p>
<p>Full code:</p>
<pre><code>
template &lt;typename Tag, std::size_t Idx&gt;
struct store
{
    friend auto lookup(store&lt;Tag, Idx&gt;);

    template &lt;typename U&gt;
    struct write
    {
        static constexpr auto index = Idx;

        public:
        friend auto lookup(store&lt;Tag, Idx&gt;)
        {
            return std::type_identity&lt;U&gt;{};
        }
    };
};

template &lt;typename Tag, std::size_t I = 0, auto Unique = [] {}&gt;
consteval auto size()
{
    if constexpr (requires { lookup(store&lt;Tag, I&gt;{}); })
    {
        return size&lt;Tag, I + 1&gt;();
    }
    else
    {
        return I;
    }
}

template &lt;typename Tag, typename T, auto Unique = []{}&gt;
consteval auto try_write()
{
    return store&lt;Tag, size&lt;Tag&gt;()&gt;::template write&lt;T&gt;::index;
}

template &lt;typename Tag, std::size_t I, auto Unique = []{}&gt;
consteval auto try_read()
{
    if constexpr (requires { lookup(store&lt;Tag, I&gt;{}); })
    {
        return lookup(store&lt;Tag, I&gt;{});
    }
    else
    {
        return std::type_identity&lt;float&gt;{};
    }
}

template &lt;typename Tag, std::size_t I, auto Unique = []{}&gt;
using try_read_t = decltype(try_read&lt;Tag, I&gt;())::type;

template &lt;typename T&gt;
struct dummy
{
    static const T value;
};

template &lt;auto T&gt;
struct nttp_dummy
{
    static constexpr auto value = 0;
};

template &lt;typename T, std::size_t Idx&gt;
struct instance : dummy&lt;T&gt;
{
    static constexpr auto index = Idx;
};

template &lt;typename Target, auto Unique = []{}&gt;
struct any
{
    template &lt;typename T, auto I = try_write&lt;Target, T&gt;()&gt;
        requires std::derived_from&lt;Target, T&gt;
    constexpr operator T();
};

template &lt;typename T, auto Unique = []{}&gt;
consteval auto direct_base()
{
    static constexpr auto idx = size&lt;T&gt;();

    if constexpr (requires { T{any&lt;T&gt;{}}; })
    {
        static constexpr auto unused = requires { T{any&lt;T&gt;{}}; }; // Force MSVC into submission
        return try_read&lt;T, idx&gt;();
    }
    else
    {
        return std::type_identity&lt;void&gt;{};
    }
}

template &lt;typename T, auto Unique = []{}&gt;
using direct_base_t = decltype(direct_base&lt;T&gt;())::type;

struct base
{
};

struct test : base
{
    int x;
};

struct another_test : test
{
    int x;
};

struct and_another_test : another_test
{
    test x;
};

static_assert(std::same_as&lt;direct_base_t&lt;test&gt;, base&gt;);
static_assert(std::same_as&lt;direct_base_t&lt;another_test&gt;, test&gt;);
static_assert(std::same_as&lt;direct_base_t&lt;and_another_test&gt;, another_test&gt;);
</code></pre>
<p>...running on MSVC/GCC/Clang: <a href="https://godbolt.org/z/4bcb4rT5T" rel="nofollow noreferrer">https://godbolt.org/z/4qcxafzx1</a><br />
Excuse the ugly double write but I could not get it to work properly on MSVC otherwise :)</p>
